// Parse config.md and resolve the requested slot → { engine, model, endpoint, flags }
// Dump the raw Fetch Config response so we can see exactly what shape it's in.
const _fc = $('Fetch Config').first().json;
const _keys = Object.keys(_fc);
const _rawStr = JSON.stringify(_fc);

// The Obsidian REST API returns the note body as a plain-text HTTP response.
// n8n's HTTP Request node JSON-encodes the body string into $json, so what we
// receive may be a single-key object like { "": "...file content..." }, or the
// content may be double-encoded with escaped quotes and newlines.
// Strategy: find the longest string value anywhere in the response object,
// then unescape it if needed.
let raw = '';
for (const val of Object.values(_fc)) {
  const s = typeof val === 'string' ? val : JSON.stringify(val);
  if (s.length > raw.length) raw = s;
}
// If it looks like a JSON-encoded string (starts with "), unwrap it once
if (raw.startsWith('"') && raw.endsWith('"')) {
  try { raw = JSON.parse(raw); } catch(_) {}
}
// Unescape escaped quotes if present
if (raw.includes('\\"')) raw = raw.replace(/\\"/g, '"');

if (!raw || raw.length < 10) {
  throw new Error(`Fetch Config returned unusable content. Keys: [${_keys.join(', ')}]. Raw (400 chars): ${_rawStr.slice(0, 400)}`);
}

const slot = $('Config').first().json.slot;

// If the content arrived as a JSON-encoded string (literal \n instead of real newlines), unescape it.
const unescaped = raw.includes('\\n') ? raw.replace(/\\n/g, '\n').replace(/\\t/g, '\t').replace(/\\r/g, '') : raw;

// Walk line-by-line to extract ```json blocks
const lines = unescaped.split('\n');
const blocks = [];
let inBlock = false;
let current = [];
for (const line of lines) {
  if (!inBlock && line.trim().startsWith('```json')) {
    inBlock = true;
    current = [];
  } else if (inBlock && line.trim() === '```') {
    blocks.push(current.join('\n'));
    inBlock = false;
    current = [];
  } else if (inBlock) {
    current.push(line);
  }
}

if (blocks.length === 0) {
  const preview = unescaped.slice(0, 600).replace(/\n/g, '↵');
  throw new Error(`No JSON blocks found in config.md. Content preview: ${preview}`);
}

let registry = null;
const parseErrors = [];
for (const block of blocks) {
  try {
    const parsed = JSON.parse(block.trim());
    if (parsed.llm_models) { registry = parsed.llm_models; break; }
  } catch (e) {
    parseErrors.push(e.message);
  }
}

if (!registry) throw new Error(`llm_models not found in config.md. Found ${blocks.length} JSON block(s). Parse errors: ${parseErrors.join('; ') || 'none — blocks parsed OK but none contained llm_models'}`);

const slotConfig = registry[slot];
if (!slotConfig) throw new Error(`Slot '${slot}' not found in llm_models registry. Available: ${Object.keys(registry).join(', ')}`);

const { engine, model, endpoint, flags = {} } = slotConfig;
if (!engine) throw new Error(`Slot '${slot}' missing required field: engine`);
if (!model)  throw new Error(`Slot '${slot}' missing required field: model`);
if (!endpoint) throw new Error(`Slot '${slot}' missing required field: endpoint`);

return [{ json: { slot, engine, model, endpoint, flags } }];

// LM Studio: eject all models from oMLX first (cross-engine RAM cleanup),
// then eject any wrong models from LM Studio, then load the target model.

// ── 0. Eject all oMLX models ──
try {
  const omlxList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://10.1.1.200:8000/v1/models',
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  if (omlxList.statusCode === 200) {
    for (const m of omlxList.body?.data || []) {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `http://10.1.1.200:8000/v1/models/${encodeURIComponent(m.id)}/unload`,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true
      });
    }
  }
} catch (_) { /* oMLX not running — fine */ }

// LM Studio: eject remaining wrong models, then load the target model.
// Uses the LM Studio proprietary API at /api/v1/models (not the OpenAI-compatible /v1/models).

const BASE = 'http://10.1.1.200:1234';
const { model, endpoint, flags, slot } = $('Resolve Slot').first().json;

// ── 1. List all loaded instances ──
const listResp = await this.helpers.httpRequest({
  method: 'GET',
  url: `${BASE}/api/v1/models`,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (listResp.statusCode !== 200) throw new Error(`LM Studio list failed: HTTP ${listResp.statusCode}`);

const allModels = listResp.body?.models || [];

// ── 2. Eject anything that isn't the target model ──
const ejected = [];
for (const m of allModels) {
  if (!m.loaded_instances?.length) continue;
  if (m.key === model) continue; // already the right model — skip
  for (const inst of m.loaded_instances) {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${BASE}/api/v1/models/unload`,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ instance_id: inst.id }),
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    ejected.push({ model: m.key, instance_id: inst.id, status: r.statusCode });
  }
}

// ── 3. Check if target is already loaded ──
const alreadyLoaded = allModels.some(m => m.key === model && m.loaded_instances?.length > 0);
if (alreadyLoaded) {
  return [{ json: { engine: 'lmstudio', model, endpoint, slot, action: 'already_loaded', ejected } }];
}

// ── 4. Load the target model ──
// LM Studio /api/v1/models/load only accepts { model } — no preset or config fields
const loadBody = { model };

const loadResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/api/v1/models/load`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(loadBody),
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (loadResp.statusCode >= 300) throw new Error(`LM Studio load failed: HTTP ${loadResp.statusCode} — ${JSON.stringify(loadResp.body)}`);

return [{ json: { engine: 'lmstudio', model, endpoint, slot, action: 'loaded', ejected } }];

// oMLX: eject all models from LM Studio first (cross-engine RAM cleanup),
// then eject any wrong models from oMLX, then load the target model.

// ── 0. Eject all LM Studio models ──
try {
  const lmslist = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://10.1.1.200:1234/api/v1/models',
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  if (lmslist.statusCode === 200) {
    for (const m of lmslist.body?.models || []) {
      if (!m.loaded_instances?.length) continue;
      for (const inst of m.loaded_instances) {
        await this.helpers.httpRequest({
          method: 'POST',
          url: 'http://10.1.1.200:1234/api/v1/models/unload',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ instance_id: inst.id }),
          returnFullResponse: true,
          ignoreHttpStatusErrors: true
        });
      }
    }
  }
} catch (_) { /* LM Studio not running — fine */ }

// oMLX: eject remaining wrong models, then load the target model.
// Uses oMLX REST API at /v1/models/{model_id}/unload and /v1/models/{model_id}/load.

const BASE = 'http://10.1.1.200:8000';
const { model, endpoint, flags, slot } = $('Resolve Slot').first().json;

// ── 1. List loaded models (OpenAI-compatible /v1/models) ──
const listResp = await this.helpers.httpRequest({
  method: 'GET',
  url: `${BASE}/v1/models`,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (listResp.statusCode !== 200) throw new Error(`oMLX list failed: HTTP ${listResp.statusCode}`);

const loadedModels = listResp.body?.data || [];

// ── 2. Eject anything that isn't the target ──
const ejected = [];
for (const m of loadedModels) {
  if (m.id === model) continue; // already the right model — skip
  const encodedId = encodeURIComponent(m.id);
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE}/v1/models/${encodedId}/unload`,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
  ejected.push({ model: m.id, status: r.statusCode });
}

// ── 3. Check if target is already loaded ──
const alreadyLoaded = loadedModels.some(m => m.id === model);
if (alreadyLoaded) {
  return [{ json: { engine: 'omlx', model, endpoint, slot, action: 'already_loaded', ejected } }];
}

// ── 4. Load the target model ──
const encodedModel = encodeURIComponent(model);
const loadResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE}/v1/models/${encodedModel}/load`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(flags || {}),
  returnFullResponse: true,
  ignoreHttpStatusErrors: true
});
if (loadResp.statusCode >= 300) throw new Error(`oMLX load failed: HTTP ${loadResp.statusCode} — ${JSON.stringify(loadResp.body)}`);

return [{ json: { engine: 'omlx', model, endpoint, slot, action: 'loaded', ejected } }];

// Poll /v1/models on the target endpoint until the model appears as loaded.
// Retries up to 20 times with 3s between attempts (60s total timeout).

const { engine, model, endpoint, slot, action, ejected } = $input.first().json;

const maxRetries = 20;
const retryDelayMs = 3000;

// For LM Studio, use the proprietary API endpoint which returns models[].key —
// the same key format used in config.md and the eject/load nodes.
// The OpenAI-compat /v1/models returns different IDs that may not match.
const modelsUrl = engine === 'lmstudio'
  ? `${endpoint.replace('/v1', '')}/api/v1/models`
  : `${endpoint}/models`;

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

let ready = false;
let attempts = 0;

while (attempts < maxRetries) {
  await sleep(attempts === 0 && action === 'already_loaded' ? 0 : retryDelayMs);
  attempts++;

  let resp;
  try {
    resp = await this.helpers.httpRequest({
      method: 'GET',
      url: modelsUrl,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
  } catch (e) {
    continue; // server not yet up
  }

  if (resp.statusCode !== 200) continue;

  const models = resp.body?.data || resp.body?.models || [];
  // OpenAI-compat: data[].id; LM Studio proprietary: models[].key
  const found = models.some(m => (m.id || m.key) === model);
  if (found) { ready = true; break; }
}

if (!ready) throw new Error(`Model '${model}' did not become ready after ${maxRetries * retryDelayMs / 1000}s (${attempts} attempts). Check engine logs on Mac Studio.`);

return [{ json: { engine, model, endpoint, slot, ready: true, action, ejected, attempts } }];
